#!/usr/bin/env python3
"""Configure disposable storage once per checkout, or run a command using it."""

import argparse
import json
import os
from pathlib import Path
import sys
import tomllib


CONFIG = Path(".cargo/scratch.local.toml")


def load_config(repo):
    path = repo / CONFIG
    if not path.is_file():
        raise ValueError("Run scratch.py configure ROOT once before using saved storage.")
    return tomllib.loads(path.read_text())


def prepare(root):
    # Never recreate an absent storage root, such as an unmounted volume.
    if not root.is_dir():
        raise ValueError(f"Storage root must already exist: {root}")
    for name in ("target", "tmp", "logs"):
        (root / name).mkdir(parents=True, exist_ok=True)


def configure(repo, root, cache_root=None):
    repo = repo.resolve()
    root = root.expanduser().resolve()
    if root == repo or root.is_relative_to((repo / "target").resolve()):
        raise ValueError("Storage root must not be the checkout or inside its target directory.")
    if not root.is_dir():
        raise ValueError(f"Storage root must already exist: {root}")
    if cache_root is not None:
        cache_root = cache_root.expanduser().resolve()
        if not cache_root.is_dir():
            raise ValueError(f"Shared cache directory must already exist: {cache_root}")
        if cache_root.is_relative_to(root) or cache_root.is_relative_to(repo):
            raise ValueError("Shared cache must be outside the checkout and its disposable root.")
        if len(os.fsencode(cache_root / "server.sock")) > 100:
            raise ValueError("Choose a shorter cache path for the sccache Unix socket.")
    target = repo / "target"
    if target.is_symlink():
        previous = None
        if (repo / CONFIG).is_file():
            previous = Path(load_config(repo)["build"]["target-dir"])
        if target.resolve() not in (root / "target", previous):
            raise ValueError("Refusing to replace an unrelated target symlink.")
    elif target.exists():
        raise ValueError("Move or clean the existing target directory before configuring storage.")

    env = {
        "TMPDIR": root / "tmp",
        "TMP": root / "tmp",
        "TEMP": root / "tmp",
    }
    if cache_root is not None:
        env.update({
            "SCCACHE_DIR": cache_root,
            "SCCACHE_SERVER_UDS": cache_root / "server.sock",
            "SCCACHE_ERROR_LOG": cache_root / "sccache.log",
        })
    def quote(value):
        return json.dumps(str(value), ensure_ascii=False)

    content = (
        "# Generated by scratch.py configure. Machine-local; do not commit.\n"
        "[build]\n"
        f"target-dir = {quote(root / 'target')}\n"
    )
    if cache_root is not None:
        content += 'rustc-wrapper = "sccache"\nincremental = false\n'
    content += "\n[env]\n"
    for key, value in env.items():
        content += f"{key} = {{ value = {quote(value)}, force = true }}\n"
    if cache_root is not None:
        # Cache normal builds; an explicit incremental workflow may opt out.
        content += 'CARGO_INCREMENTAL = { value = "0", force = false }\n'
        content += 'SCCACHE_ALLOW_INCREMENTAL = { value = "1", force = false }\n'

    prepare(root)
    if target.is_symlink():
        target.unlink()
    target.symlink_to(root / "target", target_is_directory=True)
    (repo / CONFIG).parent.mkdir(parents=True, exist_ok=True)
    (repo / CONFIG).write_text(content)


def environment(repo):
    config = load_config(repo)
    target = Path(config["build"]["target-dir"])
    cache = config["env"].get("SCCACHE_DIR")
    if cache and not Path(cache["value"]).is_dir():
        raise ValueError(f"Shared cache directory must already exist: {cache['value']}")
    prepare(target.parent)
    return {
        "CARGO_TARGET_DIR": str(target),
        **{
            key: entry["value"] for key, entry in config["env"].items()
            if entry.get("force", False) or key not in os.environ
        },
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest="action", required=True)
    configure_parser = commands.add_parser("configure", help="Save a storage root once per checkout")
    configure_parser.add_argument("root", type=Path)
    configure_parser.add_argument(
        "--sccache-dir", type=Path,
        help="Enable sccache using an existing shared directory outside checkout storage",
    )
    run_parser = commands.add_parser("run", help="Run an optional non-Cargo command with saved settings")
    run_parser.add_argument("command", nargs=argparse.REMAINDER)
    args = parser.parse_args()
    repo = Path(__file__).resolve().parents[2]
    try:
        if args.action == "configure":
            configure(repo, args.root, args.sccache_dir)
            print("Saved local storage settings. Use Cargo and Make normally.")
        else:
            if not args.command:
                parser.error("run requires a command")
            os.environ.update(environment(repo))
            os.execvp(args.command[0], args.command)
    except (OSError, ValueError, KeyError) as error:
        print(f"error: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
